// Parse the AI response and clean it
const response = $input.first().json.response;
let questions;

try {
  // Remove markdown code blocks if present
  const cleaned = response.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  questions = JSON.parse(cleaned);
} catch (error) {
  // Fallback questions if parsing fails
  questions = [
    {
      "q": `Hello! Tell me about your experience as a ${$('Webhook - Generate Questions').first().json.body.position}.`,
      "keywords": ["experience", "projects", "role", "responsibilities"],
      "type": "intro"
    },
    {
      "q": "What technical challenges have you faced recently?",
      "keywords": ["challenge", "problem", "solution", "technical"],
      "type": "technical"
    },
    {
      "q": "Describe your approach to learning new technologies.",
      "keywords": ["learning", "adapt", "study", "practice"],
      "type": "technical"
    },
    {
      "q": "How do you handle code reviews and feedback?",
      "keywords": ["feedback", "review", "improvement", "collaborate"],
      "type": "technical"
    },
    {
      "q": "What's your debugging methodology?",
      "keywords": ["debug", "testing", "logs", "systematic"],
      "type": "technical"
    },
    {
      "q": "How do you manage tight deadlines?",
      "keywords": ["prioritize", "planning", "deadline", "pressure"],
      "type": "hr"
    },
    {
      "q": "What are your career goals?",
      "keywords": ["growth", "goals", "future", "aspirations"],
      "type": "hr"
    }
  ];
}

return { json: { questions } };
